  "footer.dis1b":
    "TeraBox™ या किसी अन्य सोशल प्लेटफ़ॉर्म से जुड़ा नहीं है। हम अपने सर्वर पर कोई फ़ाइल होस्ट या स्टोर नहीं करते; सारी सामग्री उनके मूल मालिकों की है।",
  "footer.dis2":
    "कृपया कॉपीराइट या प्रतिबंधित सामग्री के लिए हमारे टूल का उपयोग न करें। केवल वही पब्लिक लिंक खोलें जिनका आपको अधिकार है।",
