  "c.eyebrow": "संपर्क करें",
  "c.titleA": "संपर्क",
  "c.titleB": "करें",
  "c.sub": "प्रश्न, बग रिपोर्ट, व्यावसायिक पूछताछ — हम मदद के लिए यहां हैं।",
  "c.m1t": "बग रिपोर्ट",
  "c.m1d": "कुछ टूटा मिला? विवरण भेजें, हम जल्द से जल्द देखेंगे।",
  "c.m1a": "बग रिपोर्ट करें",
  "c.m2t": "व्यावसायिक पूछताछ",
  "c.m2d": "साझेदारी, लाइसेंसिंग या अन्य व्यावसायिक प्रश्न। आपसे सुनकर खुशी होगी।",
  "c.m2a": "ईमेल करें",
  "c.m3t": "सामान्य फीडबैक",
  "c.m3d": "सुझाव, फीचर अनुरोध, या बस नमस्ते कहना हो। हर फीडबैक का स्वागत है।",
  "c.m3a": "फीडबैक भेजें",
  "c.emailT": "सीधे लिखना पसंद करेंगे?",
  "c.emailB": "हमें ईमेल करें, हम जल्द से जल्द जवाब देंगे।",
  "c.faqSub": "संपर्क करने से पहले आम प्रश्नों के त्वरित उत्तर।",
  "c.q1": "क्या TeraPlayer मुफ़्त है?",
  "c.a1": "हां, TeraPlayer पूरी तरह मुफ़्त है। कोई खाता नहीं, कोई छिपा शुल्क नहीं।",
  "c.q2": "क्या आप मेरा डेटा स्टोर करते हैं?",
  "c.a2": "डिफ़ॉल्ट रूप से कोई डेटा स्टोर नहीं होता। Google से साइन इन करने पर आपकी प्राथमिकताएं सिंक होती हैं। आप सारा डेटा कभी भी साफ़ कर सकते हैं।",
  "c.q3": "एक्सट्रैक्शन में कितना समय लगता है?",
  "c.a3": "ज़्यादातर लिंक 2 सेकंड से कम में रिज़ॉल्व होते हैं। बड़ी फ़ोल्डरों में 5 सेकंड तक लग सकता है।",
  "c.q4": "मेरा लिंक काम क्यों नहीं कर रहा?",
  "c.a4": "लिंक प्राइवेट या समाप्त हो सकता है, या एक्सट्रैक्टर अस्थायी रूप से अनुपलब्ध हो सकता है।",

  "atp.eyebrow": "TeraPlayer के बारे में",
  "atp.sub": "समर्थित पब्लिक TeraBox लिंक के लिए वेब टूल। लिंक पेस्ट करें, और शुरू करें।",
  "atp.s1t": "TeraPlayer क्या है?",
  "atp.s1p1": "TeraPlayer समर्थित पब्लिक TeraBox लिंक के साथ काम करने का वेब टूल है। लिंक पेस्ट करें, और सीधे ब्राउज़र में प्रीव्यू, स्ट्रीमिंग व डाउनलोड फीचर इस्तेमाल करें।",
  "atp.s1p2": "मुख्य फीचर के लिए किसी खाते की ज़रूरत नहीं।",
  "atp.s2t": "आप क्या कर सकते हैं",
  "atp.s2p1": "समर्थित पब्लिक TeraBox लिंक से TeraPlayer आपको देता है:",
  "atp.s2b1": "त्वरित प्रीव्यू — टाइटल, थंबनेल, फ़ाइल साइज़ व प्रकार",
  "atp.s2b2": "प्लेबैक कंट्रोल के साथ ब्राउज़र में सीधे वीडियो स्ट्रीम करें",
  "atp.s2b3": "समर्थित फ़ाइलें डाउनलोड करें",
  "atp.s2b4": "शेयर किए गए फ़ोल्डर ब्राउज़ करें और मल्टी-फाइल लिंक संभालें",
  "atp.s2b5": "उपलब्ध होने पर स्ट्रीम क्वालिटी चुनें",
  "atp.s3t": "यह कैसे काम करता है",
  "atp.s3p1": "लिंक पेस्ट करते ही वह TeraPlayer के बैकएंड को जाता है, जो एक्सट्रैक्शन सिस्टम से प्रोसेस करके प्रीव्यू व स्ट्रीम जानकारी लौटाता है।",
  "atp.s3p2": "फ़ाइलें TeraPlayer पर अपलोड नहीं होतीं — वे मौजूदा पब्लिक स्रोत से ही एक्सेस होती हैं।",
  "atp.s4t": "TeraPlayer क्या नहीं है",
  "atp.s4p1": "TeraPlayer TeraBox फ़ाइलें होस्ट नहीं करता, आपकी सामग्री स्टोर नहीं करता, और एक्सेस की गई किसी चीज़ का मालिकाना दावा नहीं करता।",
  "atp.s4p2": "सेवा से एक्सेस/डाउनलोड की गई सामग्री का अधिकार आपके पास होने की ज़िम्मेदारी आपकी है।",
  "atp.ctaT": "आज़माकर देखें",
  "atp.ctaB": "समर्थित TeraBox लिंक पेस्ट करें और देखें यह क्या कर सकता है।",
  "atp.ctaBtn": "TeraPlayer पर जाएं",

