  "d.faD": "TeraPlayer शेयर की हर फ़ाइल नाम, साइज़ व प्रकार सहित दिखाता है, ताकि अकेले लिंक से अंदाज़ा लगाने के बजाय वीडियो प्रीव्यू करें या ज़रूरत की ही डाउनलोड करें।",
  "d.fbT": "ZIP पैक करें",
