  "d.deepSub": "कोई जादू नहीं: तीन परतें, हर एक पिछली की छूटी संभालती है।",
  "d.d1t": "सीधा रिज़ॉल्यूशन",
  "d.d1d": "TeraPlayer पहले plain HTTP पर TeraBox के शेयर एंडपॉइंट से फ़ाइल सूची मांगता है। तेज़, हल्का, ब्राउज़र ओवरहेड नहीं — और ज़्यादातर स्वस्थ पब्लिक लिंक संभाल लेता है।",
