  "p.introT": "TeraBox प्लेयर — TeraBox वीडियो ऑनलाइन देखें",
  "p.introH": "शेयर किए गए TeraBox मीडिया के लिए ऑनलाइन ब्राउज़र प्लेबैक",
  "p.introB1": "TeraPlayer पब्लिक शेयर लिंक देखने के लिए सरल ऑनलाइन वीडियो प्लेयर देता है। सामग्री जाने बिना भारी फ़ाइलें डाउनलोड करने या बाहरी प्लेयर से जूझने के बजाय, आधुनिक डेस्कटॉप व मोबाइल ब्राउज़र में मीडिया मेटाडेटा प्रीव्यू करें व समर्थित वीडियो स्ट्रीम करें।",
  "p.introB2a": "हमारा वेब प्लेयर शेयर लिंक साफ़ रिज़ॉल्व करता है, फ़ोल्डर संरचना, मल्टी-पार्ट संग्रह व रिज़ॉल्यूशन विकल्पों को साफ़ देखने योग्य बनाता है। किसी ने TeraBox फ़ाइल शेयर की हो तो जानें",
  "p.introB2b": "पब्लिक शेयर लिंक कैसे काम करते हैं",
  "p.introB2c": "और नीचे TeraBox वीडियो ऑनलाइन कैसे देखें।",
