  "atp.eyebrow": "Acerca de TeraPlayer",
  "atp.sub": "Herramienta web para enlaces públicos de TeraBox. Pega un enlace y listo.",
  "atp.s1t": "¿Qué es TeraPlayer?",
  "atp.s1p1": "TeraPlayer es una herramienta web para enlaces públicos de TeraBox. Pega un enlace y usa la vista previa, la transmisión y la descarga en tu navegador.",
  "atp.s1p2": "Las funciones principales no necesitan cuenta.",
  "atp.s2t": "Lo que puedes hacer",
  "atp.s2p1": "Con un enlace público compatible, TeraPlayer te da:",
  "atp.s2b1": "Vista previa rápida — título, miniatura, tamaño y tipo",
  "atp.s2b2": "Transmite video en el navegador con controles",
  "atp.s2b3": "Descarga archivos compatibles",
  "atp.s2b4": "Explora carpetas y enlaces multifichero",
  "atp.s2b5": "Elige la calidad cuando esté disponible",
  "atp.s3t": "Cómo funciona",
  "atp.s3p1": "Al pegar un enlace, se envía al servidor de TeraPlayer, se procesa y devuelve la vista previa y la información de transmisión.",
  "atp.s3p2": "Los archivos no se suben a TeraPlayer — se toman de su fuente pública.",
  "atp.s4t": "Lo que TeraPlayer no es",
  "atp.s4p1": "TeraPlayer no aloja archivos de TeraBox, no guarda tu contenido ni reclama propiedad sobre lo que ves.",
  "atp.s4p2": "Eres responsable de tener derecho a acceder o descargar el contenido que uses.",
  "atp.ctaT": "Pruébalo",
  "atp.ctaB": "Pega un enlace compatible y mira lo que puede hacer.",
  "atp.ctaBtn": "Ir a TeraPlayer",

