  "hc.ctaPlayer": "Ir al reproductor de TeraBox",
  "hc.ctaDl": "Ir al descargador de TeraBox",

  "hc.pf1q": "¿Qué es un enlace público de TeraBox?",
  "hc.pf1a": "URL compartida que cualquiera con el enlace puede abrir. Si es pública, se ve sin cuenta de TeraBox.",
  "hc.pf2q": "¿Cómo uso un enlace público con TeraPlayer?",
  "hc.pf2a": "Copia el enlace público, pégalo en el descargador o reproductor y deja que TeraPlayer lo resuelva. Si es compatible muestra vista previa.",
  "hc.pf3q": "¿Abre enlaces privados?",
  "hc.pf3a": "No. TeraPlayer es para enlaces públicos compatibles. Lo privado o restringido no es accesible, sin evadir contraseñas ni DRM.",
  "hc.pf4q": "¿Por qué no funciona mi enlace público?",
  "hc.pf4a": "Puede fallar si la URL quedó incompleta, dejó de ser pública o caducó, el contenido está restringido o el dominio no es soportado.",
  "hc.pf5q": "¿Cómo hago público un enlace?",
  "hc.pf5a": "En TeraBox abre las opciones del archivo o carpeta, elige ajuste público y copia el enlace generado.",
  "hc.pf6q": "¿Puedo ver un video sin descargarlo?",
  "hc.pf6a": "Sí. Pega el enlace público compatible en el reproductor para previsualizar y transmitir sin guardar copia.",
  "hc.pf7q": "¿Puedo descargar un archivo compartido?",
  "hc.pf7a": "Sí. Cuando el enlace se resuelve en el descargador, descarga los archivos desde tu navegador.",
  "hc.pf8q": "¿Necesito cuenta para abrir un enlace?",
  "hc.pf8a": "No. TeraPlayer funciona en tu navegador. Previsualiza, mira y descarga enlaces públicos sin registrarte.",
  "hc.tf1q": "¿Por qué no funciona mi enlace?",
  "hc.tf1a": "URL incompleta, enlace no disponible, contenido privado o restringido, enlace no soportado, o problema temporal de red o navegador.",
  "hc.tf2q": "¿Por qué no se reproduce mi video?",
  "hc.tf2a": "Conexión inestable, navegador incapaz de transmitir, o enlace sin resolver. Actualiza, revisa tu conexión e inténtalo de nuevo.",
  "hc.tf3q": "¿Abre enlaces privados?",
  "hc.tf3a": "No. TeraPlayer es para enlaces públicos compatibles. Sin evadir contraseñas, autenticación ni DRM.",
  "hc.tf4q": "¿Mi enlace caducó o no está disponible?",
  "hc.tf4a": "Pide un enlace nuevo al propietario y confirma copiarlo entero. Lo eliminado o no disponible no se resuelve.",
  "hc.tf5q": "¿Por qué no funciona mi descarga?",
  "hc.tf5a": "Sin resolución del enlace público no empieza la descarga. Verifica el enlace completo y reintenta.",
  "hc.tf6q": "¿Admite todos los enlaces?",
  "hc.tf6a": "No. Solo enlaces públicos de dominios soportados. Algunos caducan, son privados o restringidos.",
  "hc.tf7q": "¿Reproductor o descargador?",
