  "c.m1d": "Menemukan yang rusak? Kirim detailnya, kami periksa sesegera mungkin.",
  "c.m1a": "Laporkan bug",
  "c.m2t": "Pertanyaan Bisnis",
  "c.m2d": "Kemitraan, lisensi, atau pertanyaan bisnis lain. Kami senang mendengarnya.",
  "c.m2a": "Email kami",
  "c.m3t": "Umpan Balik Umum",
  "c.m3d": "Saran, permintaan fitur, atau sekadar menyapa. Semua masukan diterima.",
