  "c.q1": "Apakah TeraPlayer gratis?",
  "c.a1": "Ya, TeraPlayer sepenuhnya gratis. Tanpa akun, tanpa biaya tersembunyi.",
  "c.q2": "Apakah Anda menyimpan data saya?",
  "c.a2": "Tidak ada data tersimpan secara default. Jika login Google, preferensi tersinkron ke database agar bisa diakses lintas perangkat. Anda bisa hapus semua data kapan saja.",
  "c.q3": "Berapa lama ekstraksi?",
  "c.a3": "Sebagian besar tautan teratasi di bawah 2 detik. Folder besar bisa sampai 5 detik.",
  "c.q4": "Mengapa tautan saya tidak berfungsi?",
  "c.a4": "Tautan mungkin privat, kedaluwarsa, atau mirror ekstraktor sementara tidak tersedia.",

  "atp.eyebrow": "Tentang TeraPlayer",
  "atp.sub": "Alat web untuk tautan TeraBox publik yang didukung. Tempel tautan, dan mulai.",
  "atp.s1t": "Apa itu TeraPlayer?",
  "atp.s1p1": "TeraPlayer adalah alat web untuk tautan TeraBox publik yang didukung. Tempel tautan, lalu pakai fitur pratinjau, streaming, dan unduhan langsung di browser.",
  "atp.s1p2": "Fitur inti tidak butuh akun.",
  "atp.s2t": "Yang bisa Anda lakukan",
  "atp.s2p1": "Dengan tautan TeraBox publik yang didukung, TeraPlayer memberi Anda:",
  "atp.s2b1": "Pratinjau cepat — judul, thumbnail, ukuran file, dan jenis",
  "atp.s2b2": "Streaming video langsung di browser dengan kontrol pemutaran",
  "atp.s2b3": "Unduh file yang didukung",
  "atp.s2b4": "Jelajahi folder bersama dan tautan multi-file",
  "atp.s2b5": "Pilih kualitas stream bila tersedia",
  "atp.s3t": "Cara kerjanya",
  "atp.s3p1": "Saat Anda menempel tautan, tautan dikirim ke backend TeraPlayer, diproses lewat infrastruktur ekstraksi, dan mengembalikan info pratinjau serta stream.",
  "atp.s3p2": "File tidak diunggah ke TeraPlayer — diakses dari sumber publik yang ada.",
  "atp.s4t": "Yang bukan TeraPlayer",
  "atp.s4p1": "TeraPlayer tidak menghosting file TeraBox, menyimpan konten Anda, atau mengklaim kepemilikan atas apa pun yang Anda akses.",
  "atp.s4p2": "Anda bertanggung jawab memiliki hak akses atau unduh atas konten yang dipakai.",
  "atp.ctaT": "Coba sekarang",
  "atp.ctaB": "Tempel tautan TeraBox yang didukung dan lihat kemampuannya.",
  "atp.ctaBtn": "Buka TeraPlayer",

