  "d.mob3": "Biarkan tab di depan untuk file besar agar OS tak menjeda transfer.",
  "d.pcT": "Di PC & desktop",
  "d.pc1": "Berfungsi di browser desktop modern — tanpa instal, tanpa ekstensi.",
  "d.pc2": "Browser desktop paling andal untuk transfer GB dan ZIP besar.",
  "d.pc3": "Manajer unduhan atau browser mengambil tiap file secara normal.",
  "d.foldA": "Folder & ZIP,",
  "d.foldB": "Dijelaskan",
  "d.foldSub": "Banyak berbagi berupa folder, bukan file tunggal. Begini cara TeraPlayer menanganinya.",
  "d.faT": "Jelajahi folder dulu",
  "d.faD": "TeraPlayer mencantumkan tiap file dengan nama, ukuran, dan jenis, agar bisa pratinjau video atau unduh yang perlu tanpa menebak dari satu tautan.",
  "d.fbT": "Kemas ZIP",
  "d.fbD": "Centang banyak file untuk dibundel jadi satu ZIP. Satu batasan: ZIP dirakit di memori browser. Pilihan sangat besar bisa gagal di ponsel RAM kecil, jadi bagi jadi batch kecil.",
  "d.cmpA": "TeraPlayer vs",
  "d.cmpB": "Alternatif",
  "d.cmpSub": "Tiap opsi apa adanya.",
  "d.cmpCap": "Perbandingan TeraPlayer, aplikasi resmi TeraBox, dan situs pengunduh umum",
