  "d.q1": "TeraBox ভিডিও ডাউনলোডার কী?",
  "d.a1": "TeraBox ভিডিও ডাউনলোডার পাবলিক TeraBox শেয়ার লিংক থেকে ভিডিও ফাইল সরাসরি ডিভাইসে সেভ করতে দেয় — TeraBox অ্যাপ ইনস্টল বা অ্যাকাউন্ট ছাড়াই।",
  "d.q2": "TeraBox ভিডিও কীভাবে ডাউনলোড করব?",
  "d.a2": "পাবলিক TeraBox শেয়ার লিংক কপি করে TeraPlayer ইনপুটে পেস্ট করে Watch Now চাপুন। প্রিভিউ এলে পছন্দের কোয়ালিটি বেছে Download চাপুন।",
  "d.q3": "TeraPlayer অ্যাকাউন্ট লাগবে?",
  "d.a3": "না। TeraPlayer সম্পূর্ণ ব্রাউজারে চলে। সাইন ইন ছাড়াই প্রিভিউ, দেখা ও ডাউনলোড করুন।",
  "d.q4": "ডাউনলোডের আগে ভিডিও দেখতে পারব?",
  "d.a4": "হ্যাঁ। লিংক পেস্ট করলে TeraPlayer বিল্ট-ইন প্লেয়ারসহ প্রিভিউ দেখায়, ডাউনলোড বেছে নেওয়ার আগে স্ট্রিম করতে পারেন।",
  "d.q5": "TeraBox ফোল্ডার ডাউনলোড করা যাবে?",
  "d.a5": "হ্যাঁ। শেয়ারে একাধিক ফাইল থাকলে TeraPlayer ফোল্ডার কাঠামো চিনে ব্রাউজ করতে দেয়। একাধিক ফাইল বেছে এক ZIP-এ ডাউনলোড করুন।",
  "d.q6": "মোবাইলে TeraPlayer চলবে?",
  "d.a6": "হ্যাঁ। TeraPlayer রেসপন্সিভ, মোবাইল-বান্ধব ইন্টারফেসে বানানো, যেকোনো আধুনিক মোবাইল ব্রাউজারে চলে — অ্যাপ ইনস্টল নেই।",
  "d.q7": "প্রতিটি TeraBox লিংক কি চলবে?",
  "d.a7": "TeraPlayer সমর্থিত ডোমেনের পাবলিক শেয়ার লিংক সমর্থন করে। কিছু লিংক মেয়াদোত্তীর্ণ, প্রাইভেট বা মালিক-সীমাবদ্ধ হতে পারে।",
  "d.q8": "মোবাইলে TeraBox ভিডিও ডাউনলোড করা যাবে?",
  "d.a8": "হ্যাঁ। ফোন ব্রাউজারে এই পেজ খুলে পাবলিক লিংক পেস্ট করে ডেস্কটপের মতো ডাউনলোড করুন। ফাইল Downloads বা গ্যালারিতে যায় — TeraBox অ্যাপ লাগে না।",
  "d.q9": "ZIP ডাউনলোড কীভাবে কাজ করে?",
  "d.a9": "শেয়ারে ফোল্ডার থাকলে TeraPlayer-এ খুলে চাওয়া ফাইল টিক দিয়ে এক ZIP-এ ডাউনলোড করুন। খুব বড় নির্বাচন প্যাক হতে সময় নিতে পারে কারণ ZIP ব্রাউজারে তৈরি হয়।",
