  "d.a10": "বড় ফাইল অস্থির সংযোগে সংবেদনশীল: নেটওয়ার্ক গেলে ব্রাউজার ডাউনলোড থেমে যেতে পারে। স্থিতিশীল সংযোগে আবার চেষ্টা করুন; মাল্টি-GB-তে ডেস্কটপ ব্রাউজার ভালো।",
