  "ab.pA": "গোপনীয়তা-",
  "ab.pB": "প্রথম দৃষ্টিভঙ্গি",
  "ab.pP1a": "TeraPlayer গোপনীয়তাকে মূল নীতি মেনে বানানো, পরের ভাবনা নয়।",
  "ab.pP1b": "আপনার অ্যাকাউন্ট লাগে না",
  "ab.pP1c": "ব্যবহারে — শুধু লিংক পেস্ট করে চলুন। অ্যানালিটিক্স হালকা রাখি, খোলা লিংক অ্যানালিটিক্স টুলে কখনো পাঠাই না, ব্যক্তিগত ডেটা কখনো বিক্রি করি না। পুরো জানতে",
  "ab.pP1d": "গোপনীয়তা নীতি",
  "ab.pP1e": "দেখুন।",
  "ab.pP2": "ডিভাইসে পছন্দ সিঙ্কে ঐচ্ছিক Google সাইন ইন করুন। সংরক্ষিত সব ডেটা যেকোনো সময় মুছতে পারেন।",
  "ab.pP3": "এক্সট্র্যাকশন পাইপলাইন আমাদের সার্ভারে মেটাডেটা আনে — আপনার IP থার্ড-পার্টি API-তে সরাসরি যায় না। স্ট্রিমিং প্রক্সি মিডিয়া চালানোর সময় পরিচয় গোপন রাখে।",
  "ab.rA": "পরবর্তী কী",
  "ab.rB": "আছে",
  "ab.rSub": "TeraPlayer ভবিষ্যতে কী বানাচ্ছি, এক নজর।",
  "ab.r11": "নেস্টেড সাবফোল্ডার নেভিগেশন",
  "ab.r12": "বড় ফোল্ডারে সার্ভার-সাইড ZIP",
