  "ab.r31": "মোবাইল নেটিভ অ্যাপ (iOS / Android)",
  "ab.r32": "ডেভেলপারদের API",
  "ab.r33": "সেলফ-হোস্টারদের PostgreSQL অ্যাডাপ্টার",
  "ab.tA": "আস্থা ও",
  "ab.tB": "স্বচ্ছতা",
  "ab.tP1": "TeraPlayer স্বতন্ত্র প্রজেক্ট। আমরা খোলাখুলি বলি সেবাটি কী, কীভাবে কাজ করে, সীমা কী।",
  "ab.tP2a": "কোনো অফিসিয়াল অংশীদারত্ব নেই:",
  "ab.tP2b": "TeraPlayer TeraBox, Flextech বা কোনো ক্লাউড স্টোরেজের অনুমোদিত, সমর্থিত বা স্পন্সরড নয়। সব ট্রেডমার্ক মালিকদের।",
  "ab.tP3a": "কোনো গ্যারান্টি নেই:",
  "ab.tP3b": "প্রতিশ্রুতি দিই না প্রতিটি লিংক চলবে। শেয়ার প্রাপ্যতা বদলায়, লিংক মেয়াদোত্তীর্ণ হয়, কিছু ডোমেন সমর্থিত নয়। না চললে স্বচ্ছ থাকি।",
  "ab.tP4a": "স্ট্যাক নিয়ে খোলামেলা:",
  "ab.tP4b": "TeraPlayer React, Python/FastAPI, Cloudflare Workers ও MongoDB-তে চলে। এক্সট্র্যাকশন পাইপলাইনে নেটিভ HTTP স্ক্র্যাপিং, সেলফ-হোস্টেড Worker ও কমিউনিটি API-এর মিশ্রণ। পুরো টেকনিক্যাল স্ট্যাকে",
  "ab.tP4c": "About TeraPlayer",
  "ab.tP4d": "পেজ দেখুন।",
  "ab.tP5a": "ডিফল্ট গোপনীয়তা:",
  "ab.tP5b": "মূল ফিচারে অ্যাকাউন্ট লাগে না। অ্যানালিটিক্স (PostHog, Google Analytics) ও বিজ্ঞাপন (Google AdSense) শুধু স্পষ্ট সম্মতির পর লোড হয়। পুরো জানতে",
  "ab.tP5c": "গোপনীয়তা নীতি",
  "ab.tP5d": "দেখুন।",
  "ab.eA": "এক্সট্র্যাকশন কীভাবে",
  "ab.eB": "কাজ করে",
  "ab.eSub": "আপনার লিংক রিজলভ করা মাল্টি-লেয়ার পাইপলাইনে স্বচ্ছ নজর।",
  "ab.e1t": "নেটিভ HTTP স্ক্র্যাপার",
  "ab.e1d": "শেয়ার এন্ডপয়েন্টে সরাসরি HTTP অনুরোধে প্রথম-পাস এক্সট্র্যাকশন। দ্রুত, হালকা, ব্রাউজার ওভারহেড নেই।",
  "ab.e2t": "Cloudflare Worker",
  "ab.e2sub": "সেলফ-হোস্টেড",
