  "ab.ctaB": "TeraBox লিংক পেস্ট করে পার্থক্য দেখুন — সাইনআপ লাগে না।",
  "ab.ctaBtn": "TeraPlayer-এ যান",
  "ab.disc": "দাবিত্যাগ:",
  "ab.discB": "TeraPlayer স্বতন্ত্র টুল এবং",
  "ab.discC": "অনুমোদিত নয়",
  "ab.discD": ", TeraBox বা Flextech সমর্থিত/স্পন্সরড নয়। সব ট্রেডমার্ক ও কনটেন্ট মালিকদের। TeraPlayer শুধু পাবলিক শেয়ার কনটেন্ট অ্যাক্সেস করে, কপিরাইট উপাদান হোস্ট, স্টোর বা বণ্টন করে না। এখতিয়ার আইন মানার দায়িত্ব ইউজারদের।",
  "cpr.eyebrow": "আইনি",
  "cpr.titleB": "ও মেধাস্বত্ব",
