  "cpr.s1t": "কপিরাইট সম্মান",
  "cpr.s1p1": "TeraPlayer কপিরাইট ও মেধাস্বত্ব সম্মান করে। থার্ড-পার্টি সেবার কনটেন্টের মালিকানা দাবি করি না, সেবা দিয়ে যাওয়া ফাইল হোস্ট/স্টোর করি না।",
  "cpr.s1p2": "TeraPlayer দিয়ে অ্যাক্সেস/ডাউনলোড করা কনটেন্টের অনুমতি আপনার আছে নিশ্চিত করা আপনার দায়িত্ব।",
  "cpr.s1p3": "TeraPlayer শুধু পাবলিক শেয়ার লিংক প্রসেস করে। পেওয়াল, DRM, অথেনটিকেশন বা অন্য অ্যাক্সেস কন্ট্রোল বাইপাস করি না। শেয়ার পাবলিক না হলে অ্যাক্সেস হবে না।",
  "cpr.s2t": "লঙ্ঘন মনে হলে",
