  "cpr.s3p2": "নোট: স্বতন্ত্র টুল হিসেবে TeraPlayer এই অনুরোধ অনানুষ্ঠানিক সামলায়। DMCA ফাইলিংয়ের মতো আনুষ্ঠানিক আইনি প্রক্রিয়া চালাই না, ইউজার-মালিক বিরোধে মধ্যস্থতা করতে পারি না।",
