  "cpr.s4b4": "TeraPlayer গ্যারান্টি দেয় না প্রতিটি লিংক সবসময় চলবে — শেয়ার প্রাপ্যতা বদলায়",
  "cpr.s4b5": "TeraPlayer TeraBox, Flextech বা কোনো ক্লাউড স্টোরেজের অনুমোদিত নয়",
