  "hc.tsSub": "ক্রমে এই ধাপগুলো করুন। প্রতিটি বলে কী দেখবেন, কেন জরুরি, পরে কী করবেন। সব লিংক ঠিক হবে না, তবে সাধারণ সমস্যা কভার করে মালিকের কাছে নতুন লিংক চাওয়ার আগে পরিষ্কার শুরু দেয়।",
