  "hc.invP2": "সমাধান সহজ: TeraBox থেকে পুরো পাবলিক শেয়ার URL কপি করে পুরো ঠিকানা নির্বাচিত নিশ্চিত করে সরাসরি TeraPlayer-এ পেস্ট করুন। URL-এর ছুটে যাওয়া অংশই ব্যর্থতার জন্য যথেষ্ট।",
  "hc.invP3": "আগে সাদা টেক্সট এডিটরে পেস্ট করলে ঠিক কী কপি হয়েছে দেখা যায়। আশপাশের অক্ষর, লুকানো স্পেস বা লাইন ব্রেক দেখে TeraPlayer-এ পরিষ্কার লিংক পেস্টের আগে মোছা সহজ হয়।",
  "hc.plT": "কী",
  "hc.plB": "TeraBox পাবলিক লিংক?",
