  "hc.plP2": "পাবলিক শেয়ার প্রাইভেট থেকে আলাদা। প্রাইভেট/সীমাবদ্ধ শেয়ার কনটেন্ট মালিকের অ্যাকাউন্টের পেছনে রাখে, খুলতে সঠিক ক্রেডেনশিয়াল লাগে। সাদা লিংকে শুধু পাবলিক শেয়ার খোলে, তাই TeraPlayer-এর মতো টুল প্রাইভেটের বদলে পাবলিক লিংক নেয়।",
