  "d.d1t": "الحل المباشر",
  "d.d1d": "يطلب TeraPlayer أولًا نقاط مشاركة TeraBox عبر HTTP لقائمة الملفات. سريع وخفيف دون عبء المتصفح — ويعالج معظم الروابط العامة السليمة.",
