  "d.q1": "ما هو منزّل فيديو TeraBox؟",
  "d.a1": "منزّل فيديو TeraBox يحفظ ملفات الفيديو من روابط مشاركة TeraBox العامة مباشرة إلى جهازك — دون تثبيت التطبيق أو إنشاء حساب.",
  "d.q2": "كيف أنزّل فيديو TeraBox؟",
  "d.a2": "انسخ رابط مشاركة عامًا والصقه في حقل TeraPlayer واضغط Watch Now. بعد تحميل المعاينة اختر الجودة واضغط زر التنزيل.",
  "d.q3": "هل أحتاج حساب TeraPlayer؟",
  "d.a3": "لا. يعمل TeraPlayer بالكامل في متصفحك. عاين وشاهد ونزّل روابط TeraBox العامة دون تسجيل.",
  "d.q4": "هل يمكنني المشاهدة قبل التنزيل؟",
  "d.a4": "نعم. بعد لصق الرابط يعرض TeraPlayer معاينة بمشغّل مدمج لتبث الفيديو قبل اختيار التنزيل.",
  "d.q5": "هل يمكنني تنزيل مجلدات TeraBox؟",
  "d.a5": "نعم. عندما تحتوي المشاركة ملفات متعددة يكتشف TeraPlayer بنية المجلد. حدد ملفات متعددة ونزّلها كأرشيف ZIP واحد.",
  "d.q6": "هل يعمل على الجوال؟",
  "d.a6": "نعم. TeraPlayer متجاوب ومناسب للجوال ويعمل في أي متصفح حديث — دون تثبيت تطبيق.",
  "d.q7": "هل يعمل مع كل روابط TeraBox؟",
  "d.a7": "يدعم TeraPlayer روابط المشاركة العامة من النطاقات المدعومة. بعض الروابط قد تكون منتهية أو خاصة أو مقيدة.",
  "d.q8": "هل يمكنني التنزيل على الجوال؟",
  "d.a8": "نعم. افتح هذه الصفحة في متصفح هاتفك والصق الرابط العام ونزّل كما على سطح المكتب. تُحفظ الملفات في التنزيلات أو المعرض — دون تطبيق TeraBox.",
  "d.q9": "كيف تعمل تنزيلات ZIP؟",
  "d.a9": "عند احتواء المشاركة مجلدًا افتحه في TeraPlayer وعلّم الملفات ونزّلها كأرشيف واحد. الاختيارات الضخمة قد تستغرق وقتًا لأن ZIP يُجمّع في متصفحك.",
  "d.q10": "لماذا فشل تنزيلي الكبير في المنتصف؟",
  "d.a10": "الملفات الكبيرة حساسة للاتصال غير المستقر: إذا انقطعت الشبكة قد يتوقف التنزيل. أعد المحاولة باتصال ثابت، وللغيغابايتات فضّل متصفح سطح المكتب.",
  "d.crossChip": "تفضل البث بدلًا من ذلك؟",
