  "p.introB1": "يوفر TeraPlayer مشغّل فيديو بسيطًا عبر الإنترنت لروابط المشاركة العامة. بدل تنزيل ملفات ثقيلة قبل معرفة محتواها، عاين البيانات الوصفية وابدأ بث الصيغ المدعومة مباشرة في متصفحات سطح المكتب والجوال الحديثة.",
  "p.introB2a": "يحل مشغّل الويب الروابط المشتركة بدقة، منظمًا بنى المجلدات والمجموعات متعددة الأجزاء وخيارات الدقة في تجربة مشاهدة نظيفة. إذا شاركك أحدهم ملف TeraBox، تعلم كيف تعمل",
