  "p.a1": "مشغّل فيديو TeraBox أداة ويب تفتح روابط مشاركة TeraBox العامة المدعومة وتبث المحتوى مباشرة في متصفحك دون استخراج يدوي أو برامج ثقيلة.",
  "p.q2": "كيف أشاهد فيديو TeraBox عبر الإنترنت؟",
  "p.a2": "انسخ رابطًا عامًا مدعومًا والصقه في شريط البحث أعلى الصفحة واضغط Watch Now. سيحل TeraPlayer الرابط ويعرض مشغّلًا مدمجًا.",
  "p.q3": "هل أحتاج حساب TeraPlayer للمشاهدة؟",
