  "p.q4": "هل يمكنني المشاهدة على الهاتف أو الجهاز اللوحي؟",
  "p.a4": "نعم. TeraPlayer محسّن لمتصفحات الجوال بما فيها Chrome وSafari وFirefox وEdge على Android وiOS.",
  "p.q5": "هل يمكنني اختيار جودات مختلفة؟",
  "p.a5": "عند احتواء الرابط ملفات متعددة الدقة يعرض TeraPlayer منتقي جودة لاختيار الدقة قبل التشغيل.",
  "p.q6": "هل يمكنني التنزيل بعد المشاهدة؟",
  "p.a6": "نعم. يشمل TeraPlayer البث والتنزيل. لحفظ ملف دون اتصال بعد المعاينة استخدم أدوات التنزيل المدمجة أو صفحة المنزّل.",
  "p.q7": "هل يدعم كل روابط TeraBox؟",
  "p.a7": "يدعم روابط المشاركة العامة القياسية. الملفات الخاصة والمحذوفة والمنتهية والمقيدة لا يمكن استخراجها أو تشغيلها.",
  "p.q8": "هل يتذكر المشغّل موضع التوقف؟",
  "p.a8": "نعم، ضمن جلسة المتصفح نفسها. إذا توقفت وعدت لنفس الفيديو يعرض الاستئناف من آخر موضع. لا تغادر بيانات الاستئناف جهازك وتُمسح بانتهاء الجلسة.",
  "p.q9": "هل تعمل صورة داخل صورة أو اختصارات لوحة المفاتيح؟",
  "p.a9": "نعم. يدعم صورة داخل صورة وملء الشاشة والسرعة المتغيرة والاختصارات: Space/K للتشغيل والإيقاف، وJ/L أو الأسهم للتنقل، وM للكتم، وF لملء الشاشة.",
