  "footer.tagline":
    "TeraPlayer TeraBox लिङ्क खोल्ने र मौलिक क्वालिटीमा भिडियो हेर्ने सुपर-फास्ट वेब टुल हो — सरल, छिटो र निःशुल्क।",
