  "footer.dis1b":
    "TeraBox™ वा अन्य सामाजिक प्लेटफर्मसँग आबद्ध छैन। हामी सर्भरमा कुनै फाइल होस्ट वा भण्डारण गर्दैनौं; सबै सामग्री मूल मालिकहरूकै हो।",
  "footer.dis2":
    "प्रतिलिपि अधिकारयुक्त वा प्रतिबन्धित सामग्रीका लागि हाम्रो टुल प्रयोग नगर्नुहोस्। पहुँच अधिकार भएका सार्वजनिक लिङ्क मात्र खोल्नुहोस्।",
