  "c.q1": "के TeraPlayer निःशुल्क हो?",
  "c.a1": "हो, TeraPlayer पूर्ण निःशुल्क छ। खाता छैन, लुकेको शुल्क छैन।",
  "c.q2": "के तपाईं मेरो डेटा भण्डारण गर्नुहुन्छ?",
  "c.a2": "डिफल्ट रूपमा कुनै डेटा भण्डारण हुँदैन। Google बाट साइन इन गरे प्राथमिकता सिङ्क हुन्छ। जुनसुकै बेला सबै डेटा हटाउन सक्नुहुन्छ।",
  "c.q3": "एक्स्ट्र्याक्सनमा कति समय लाग्छ?",
  "c.a3": "धेरैजसो लिङ्क २ सेकेन्डभित्र रिजोल्ब हुन्छन्। ठूला फोल्डरमा ५ सेकेन्ड लाग्न सक्छ।",
  "c.q4": "मेरो लिङ्क किन चलेन?",
