  "atp.eyebrow": "TeraPlayer बारे",
  "atp.sub": "समर्थित सार्वजनिक TeraBox लिङ्कका लागि वेब टुल। लिङ्क पेस्ट गर्नुहोस्, सुरु गर्नुहोस्।",
  "atp.s1t": "TeraPlayer के हो?",
  "atp.s1p1": "TeraPlayer समर्थित सार्वजनिक TeraBox लिङ्कका लागि वेब टुल हो। लिङ्क पेस्ट गर्नुहोस्, सिधै ब्राउजरमा प्रिभ्यु, स्ट्रिमिङ र डाउनलोड प्रयोग गर्नुहोस्।",
