  "atp.s2b4": "साझा फोल्डर ब्राउज र मल्टी-फाइल लिङ्क",
  "atp.s2b5": "उपलब्ध हुँदा स्ट्रिम क्वालिटी छान्नुहोस्",
  "atp.s3t": "यसले कसरी काम गर्छ",
  "atp.s3p1": "लिङ्क पेस्ट गर्दा त्यो TeraPlayer ब्याकएन्डमा जान्छ, एक्स्ट्र्याक्सन प्रणालीबाट प्रोसेस भएर प्रिभ्यु र स्ट्रिम जानकारी फर्काउँछ।",
  "atp.s3p2": "फाइल TeraPlayer मा अपलोड हुँदैनन् — अवस्थित सार्वजनिक स्रोतबाटै लिइन्छ।",
  "atp.s4t": "TeraPlayer के होइन",
  "atp.s4p1": "TeraPlayer TeraBox फाइल होस्ट गर्दैन, तपाईंको सामग्री भण्डारण गर्दैन, र पहुँच गरेको कुराको स्वामित्व दाबी गर्दैन।",
  "atp.s4p2": "प्रयोग गरेको सामग्री पहुँच/डाउनलोड गर्ने अधिकार तपाईंसँग हुने जिम्मा तपाईंको हो।",
