  "d.deepSub": "कुनै जादु छैन: तीन तह, हरेकले अघिल्लोको छुटेको संभाल्छ।",
  "d.d1t": "प्रत्यक्ष रिजोल्युसन",
  "d.d1d": "TeraPlayer ले पहिले सादा HTTP मा TeraBox शेयर पोइन्टबाट फाइल सूची माग्छ। छिटो, हलुका, ब्राउजर भार छैन — धेरैजसो स्वस्थ सार्वजनिक लिङ्क संभाल्छ।",
