  "p.introB2a": "हाम्रो वेब प्लेयरले शेयर लिङ्क सफासँग रिजोल्ब गर्छ, फोल्डर संरचना, मल्टी-पार्ट सङ्ग्रह र रिजोल्युसन विकल्पलाई सफा हेर्ने अनुभवमा मिलाउँछ। कसैले TeraBox फाइल शेयर गरेको छ भने जान्नुहोस्",
