  "p.q1": "TeraBox भिडियो प्लेयर के हो?",
  "p.a1": "TeraBox भिडियो प्लेयर अनलाइन वेब टुल हो जसले समर्थित सार्वजनिक शेयर लिङ्क खोलेर सिधै ब्राउजरमा भिडियो स्ट्रिम गर्छ, म्यानुअल एक्स्ट्र्याक्सन वा भारी सफ्टवेयर बिना।",
