  "p.a2": "समर्थित सार्वजनिक लिङ्क कपी गरी यो पेजको माथिल्लो सर्च बारमा पेस्ट गरी Watch Now थिच्नुहोस्। TeraPlayer ले लिङ्क रिजोल्ब गरी एकीकृत प्लेयर देखाउँछ।",
  "p.q3": "हेर्न TeraPlayer खाता चाहिन्छ?",
  "p.a3": "समर्थित सार्वजनिक लिङ्क रिजोल्ब र स्ट्रिम गर्न खाता वा दर्ता आवश्यक छैन।",
