  "p.q6": "हेरेपछि डाउनलोड गर्न सक्छु?",
  "p.a6": "हो। TeraPlayer मा स्ट्रिमिङ र डाउनलोडिङ दुवै छन्। प्रिभ्युपछि अफलाइन सेभ गर्नु छ भने बिल्ट-इन डाउनलोड नियन्त्रण वा डाउनलोडर पेज प्रयोग गर्नुहोस्।",
  "p.q7": "के हरेक TeraBox लिङ्क चल्छ?",
  "p.a7": "TeraPlayer ले मानक सार्वजनिक शेयर लिङ्क समर्थन गर्छ। निजी फाइल, मेटिएका सामग्री, म्याद सकिएका शेयर वा प्रतिबन्धित लिङ्क एक्स्ट्र्याक्ट/प्ले हुँदैनन्।",
  "p.q8": "के प्लेयरले रोकिएको ठाउँ सम्झन्छ?",
  "p.a8": "हो, उही ब्राउजर सत्रमा। रोकेर उही भिडियोमा फर्कंदा पछिल्लो ठाउँबाट रिज्युम गर्ने विकल्प मिल्छ। रिज्युम डेटा डिभाइस छोड्दैन, सत्र सकिँदा मेटिन्छ।",
  "p.q9": "के पिक्चर-इन-पिक्चर वा किबोर्ड सर्टकट चल्छ?",
  "p.a9": "हो। प्लेयरले पिक्चर-इन-पिक्चर, फुलस्क्रिन, परिवर्तनशील गति र सर्टकट समर्थन गर्छ: चलाउन/रोक्न Space/K, सीक गर्न J/L वा एरो, म्यूट गर्न M, फुलस्क्रिन गर्न F।",
