  "ab.wP2a": "यसले बहु-तह एक्स्ट्र्याक्सन पाइपलाइन प्रयोग गर्छ: नेटिभ HTTP स्क्रैपर, सेल्फ-होस्टेड Cloudflare Worker र सामुदायिक वैकल्पिक API। एउटा असफल भए अर्कोले सम्हाल्छ। नतिजा हो",
