  "hc.tsT": "काम नगर्ने TeraBox लिङ्क",
  "hc.tsB": "कसरी ठीक गर्ने",
  "hc.tsSub": "क्रमैसँग यी चरण अपनाउनुहोस्। हरेकले के जाँच्ने, किन महत्त्वपूर्ण, अर्को के गर्ने बताउँछ। हरेक लिङ्क ठीक हुँदैनन्, तर सामान्य समस्या समेट्छन् र मालिकसँग नयाँ लिङ्क माग्नुअघि स्पष्ट सुरुवात दिन्छन्।",
  "hc.ts1t": "पूरा लिङ्क कपी भएको पक्का गर्नुहोस्",
  "hc.ts1d": "TeraBox बाट पूरा शेयर लिङ्क खोल्नुहोस् र कपीअघि पूरा URL छानिएको पक्का गर्नुहोस्। आंशिक लिङ्क रिजोल्ब हुँदैन।",
  "hc.ts2t": "शेयर अझै उपलब्ध छ पक्का गर्नुहोस्",
  "hc.ts2d": "शेयर मेटिन वा अनुपलब्ध हुन सक्छन्। मालिकसँग शेयर सक्रिय नभए लिङ्क रिजोल्ब हुँदैन।",
  "hc.ts3t": "शेयर सार्वजनिक छ पक्का गर्नुहोस्",
  "hc.ts3d": "TeraPlayer समर्थित सार्वजनिक शेयर लिङ्कसँग काम गर्छ। निजी/प्रतिबन्धित शेयर पहुँच हुँदैन।",
  "hc.ts4t": "सही टुल प्रयास गर्नुहोस्",
  "hc.ts4d": "स्ट्रिमिङलाई भिडियो प्लेयर, समर्थित भिडियो सेभलाई भिडियो डाउनलोडर प्रयोग गर्नुहोस्।",
  "hc.ts5t": "ब्राउजर र जडान जाँच्नुहोस्",
  "hc.ts5d": "ढिलो/अस्थिर जडानले अनुरोध रोक्न सक्छ। एकपटक रिफ्रेश गरी लिङ्क पुनः प्रयास गर्नुहोस्।",
  "hc.ts6t": "लिङ्क फेरि प्रयास गर्नुहोस्",
  "hc.ts6d": "केही असफलता अस्थायी हुन्छन्। छोटो पर्खाइपछि फेरि पेस्ट गरी रिजोल्ब हुन्छ कि हेर्नुहोस्।",
  "hc.invT": "TeraBox लिङ्क",
  "hc.invB": "अमान्य वा अपूर्ण",
  "hc.invP1": "शेयर लिङ्क असफल हुनुको सामान्य कारण URL नै अपूर्ण हुनु हो। यस्तो तब हुन्छ जब:",
  "hc.invB1": "URL पूरा कपी हुनुअघि काटियो।",
  "hc.invB2": "लिङ्कमा गल्तीले स्पेस वा लाइन ब्रेक पस्यो।",
  "hc.invB3": "URL सँगै वरपरको थप पाठ पनि कपी भयो।",
  "hc.invB4": "लिङ्क छोटो पारियो वा हातले जोडियो।",
  "hc.invP2": "समाधान सजिलो छ: TeraBox बाट पूरा सार्वजनिक शेयर URL कपी गरी पूरा ठेगाना छानिएको पक्का गरी सिधै TeraPlayer मा पेस्ट गर्नुहोस्। छुटेको भाग नै असफलताका लागि काफी छ।",
  "hc.invP3": "पहिले सादा पाठ सम्पादकमा पेस्ट गर्दा ठ्याक्कै के कपी भयो देखिन्छ। वरपरका अक्षर, लुकेका स्पेस वा लाइन ब्रेक देखेर TeraPlayer मा सफा लिङ्क पेस्टअघि हटाउन सजिलो हुन्छ।",
  "hc.plT": "के हो",
  "hc.plB": "TeraBox सार्वजनिक लिङ्क?",
  "hc.plP1": "TeraBox मा कसैले फाइल/फोल्डर शेयर गर्दा त्यसलाई URL दिइन्छ। शेयर सार्वजनिक भए पाउने जोकसैले मूल खाता पहुँच बिना खोल्न सक्छ। धेरैजसो शेयर यस्तै लिङ्क बनाउँछन्।",
  "hc.plP2": "सार्वजनिक शेयर निजीभन्दा फरक छ। निजी/प्रतिबन्धित शेयर सामग्री मालिकको खातापछाडि राख्छ, खोल्न सही प्रमाण चाहिन्छ। सादा लिङ्कले सार्वजनिक मात्र खुल्छन्, त्यसैले TeraPlayer जस्ता टुलले निजीका साटो सार्वजनिक लिङ्क लिन्छन्।",
  "hc.plP3": "सार्वजनिक शेयर समयसँग बदलिन पनि सक्छन्। मालिकले शेयर मेट्न, लिङ्क रिसेट गर्न वा प्रकाशनपछि सीमित गर्न सक्छ। त्यसैले हिजो चलेको लिङ्क आज नखुल्न सक्छ।",
  "hc.vsT": "सार्वजनिक बनाम निजी",
  "hc.vsB": "TeraBox लिङ्क",
  "hc.vsAt": "सार्वजनिक लिङ्क",
  "hc.vsAd": "URL हुने जोकसैले खोल्न सक्छ। समर्थित डोमेनका सार्वजनिक शेयर नै TeraPlayer ले समर्थन गर्छ, शेयर रहेसम्म।",
  "hc.vsBt": "निजी वा प्रतिबन्धित",
  "hc.vsBd": "खोल्न मालिकको खाता/प्रमाण चाहिन्छ। TeraPlayer यो सामग्री पहुँच गर्न सक्दैन, पासवर्ड, प्रमाणीकरण, DRM छल्दैन।",
  "hc.vsNote": "पठाइएको लिङ्क TeraPlayer मा नखुले सम्भवतः दोस्रो वर्गमा पर्छ, वा सार्वजनिक शेयर म्याद सकिएको/मेटिएको छ।",
