  "hc.whyB": "किन असफल हुन सक्छ",
  "hc.whySub": "सार्वजनिक लिङ्क पनि तपाईंको नियन्त्रणबाहिर कारणले असफल हुन सक्छ। सामान्य कारण:",
  "hc.w1t": "अपूर्ण URL",
  "hc.w1d": "लिङ्क पूरा कपी भएन, वा थप अक्षर परे। आंशिक URL रिजोल्ब हुँदैन।",
  "hc.w2t": "शेयर अब सार्वजनिक छैन",
  "hc.w2d": "मालिकले प्रकाशनपछि शेयर सीमित वा लिङ्क रिसेट गरेको हुन सक्छ।",
  "hc.w3t": "म्याद सकिएको/मेटिएको शेयर",
