  "hc.w4t": "असमर्थित लिङ्क",
  "hc.w4d": "TeraPlayer समर्थित डोमेनका सार्वजनिक शेयर लिङ्कसँग काम गर्छ। केही लिङ्क समर्थित छैनन्।",
