  "hc.pbNoteA": "स्ट्रिमिङलाई",
  "hc.pbNotePlayer": "TeraBox भिडियो प्लेयर",
  "hc.pbNoteB": "प्रयोग गर्नुहोस्। डिभाइसमा समर्थित भिडियो सेभलाई",
  "hc.pbNoteDl": "TeraBox भिडियो डाउनलोडर",
  "hc.dlT": "TeraBox डाउनलोड",
  "hc.dlB": "काम गरिरहेको छैन",
  "hc.dlP1": "तीन कुरा छुट्याउनु सहयोगी हुन्छ: लिङ्क रिजोल्ब गर्ने, भिडियो चलाउने, डाउनलोड गर्ने। समर्थित सार्वजनिक शेयर रिजोल्ब भएपछि मात्र डाउनलोड सम्भव हुन्छ। रिजोल्युसन असफल भए सेटिङ बदल्दा आवश्यक समाधान हुँदैन।",
  "hc.dlP2": "लिङ्क रिजोल्ब भएर प्लेब्याक चले डाउनलोड समस्या सामान्यतया फाइलको ब्राउजर प्रयोगमा हुन्छ। लिङ्क नै रिजोल्ब नभए सेटिङ जे भए पनि डाउनलोड सुरु हुँदैन।",
  "hc.dlP3": "उल्टो पनि उही तर्क हो: रिजोल्ब भएर स्ट्रिम हुने लिङ्क अनिवार्य डाउनलोड समस्या होइन। कुन चरण असफल — रिजोल्युसन, प्लेब्याक वा डाउनलोड — यसले कहाँ हेर्ने र कुन टुल प्रयोग गर्ने बताउँछ।",
  "hc.dlP4a": "पूरा प्रक्रियाका लागि हाम्रो निर्देशिका हेर्नुहोस्",
  "hc.dlP4b": "TeraBox भिडियो डाउनलोडर",
  "hc.pvdT": "TeraBox प्रयोग गर्ने",
