  "hc.pvdAd": "ब्राउजरमा समर्थित भिडियो प्रिभ्यु र स्ट्रिमका लागि।",
  "hc.pvdBt": "TeraBox भिडियो डाउनलोडर",
  "hc.pvdBd": "डिभाइसमा समर्थित भिडियो सेभका लागि।",
  "hc.stillT": "TeraBox लिङ्क अझै",
  "hc.stillB": "काम नगरे के गर्ने",
  "hc.stillP1": "केही लिङ्क समर्थित/उपलब्ध नै नहुन सक्छन्, कुनै समस्या-समाधान चरणले रिजोल्ब गर्दैन। यो सामान्य हो — हरेक शेयर TeraPlayer मा खुल्दैन।",
  "hc.stillB1": "पठाउनेसँग मूल शेयर प्रमाणित गर्नुहोस्।",
  "hc.stillB2": "मालिकसँग नयाँ सार्वजनिक शेयर माग्नुहोस्।",
  "hc.stillB3": "URL पूरा कपी भएको पक्का गर्नुहोस्।",
  "hc.stillB4": "अस्थायी नेटवर्क समस्या भए पछि फेरि प्रयास गर्नुहोस्।",
  "hc.stillB5": "हेर्ने/डाउनलोड गर्न उपयुक्त टुल प्रयास गर्नुहोस्।",
  "hc.stillP2": "हरेक लिङ्कको पक्का समाधान छैन। शेयर साँच्चै अनुपलब्ध भए एकमात्र भरपर्दो अर्को कदम मालिकबाट काम गर्ने सार्वजनिक शेयर लिनु हो।",
  "hc.stillP3": "के प्रयास गर्नुभयो रेकर्ड राख्नुहोस् ताकि शेयर मालिकलाई ठ्याक्कै भन्न सक्नुहोस्, जस्तै लिङ्क रिजोल्ब भयो कि प्लेब्याकमै असफल भयो। यसले शेयर सार्वजनिक र खुला छ भनी पुष्टि गर्न सहयोग गर्छ।",
  "hc.faqAEyebrow": "सार्वजनिक लिङ्क प्रश्न",
  "hc.faqAT": "TeraBox सार्वजनिक लिङ्क",
