  "hc.pf1q": "TeraBox सार्वजनिक लिङ्क के हो?",
  "hc.pf1a": "सार्वजनिक लिङ्क त्यो शेयर URL हो जसबाट लिङ्क हुने जोकसैले साझा फाइल खोल्न सक्छ। शेयर सार्वजनिक सेट हुँदा TeraBox खाताबिना सामग्री हेर्न सकिन्छ।",
  "hc.pf2q": "TeraPlayer सँग सार्वजनिक लिङ्क कसरी प्रयोग गर्ने?",
  "hc.pf2a": "सार्वजनिक शेयर लिङ्क कपी गरी डाउनलोडर/प्लेयरमा पेस्ट गरी TeraPlayer लाई रिजोल्ब गर्न दिनुहोस्। समर्थित सार्वजनिक लिङ्क भए फाइल/फोल्डर प्रिभ्यु देखाउँछ।",
  "hc.pf3q": "के TeraPlayer ले निजी लिङ्क खोल्न सक्छ?",
  "hc.pf3a": "सक्दैन। TeraPlayer समर्थित सार्वजनिक शेयर लिङ्कका लागि हो। निजी/प्रतिबन्धित सामग्री पहुँच हुँदैन, पासवर्ड, प्रमाणीकरण, DRM छलिँदैन।",
  "hc.pf4q": "मेरो सार्वजनिक लिङ्क किन काम गरिरहेको छैन?",
  "hc.pf4a": "URL पूरा कपी नभए, शेयर सार्वजनिक नरहे/म्याद सकिए, सामग्री प्रतिबन्धित भए, वा डोमेन असमर्थित भए असफल हुन सक्छ। पूरा URL जाँचेर शेयर सार्वजनिक छ पक्का गर्नुहोस्।",
  "hc.pf5q": "TeraBox लिङ्क सार्वजनिक कसरी बनाउने?",
